  1	import { readFile } from 'node:fs/promises';
  2	import { createServer } from 'node:http';
  3	import { extname, join } from 'node:path';
  4	import { fileURLToPath } from 'node:url';
  5	import { loadConfig } from './core/config/load.js';
  6	import { readSnapshot } from './data.js';
  7	import { escapeHtml } from './html.js';
  8	import { layout } from './layout.js';
  9	import { renderAlerts } from './pages/alerts.js';
 10	import { renderAudit } from './pages/audit.js';
 11	import { renderBackups } from './pages/backups.js';
 12	import { renderCapacity } from './pages/capacity.js';
 13	import { renderCertificates } from './pages/certificates.js';
 14	import { renderChanges } from './pages/changes.js';
 15	import { renderClusters } from './pages/clusters.js';
 16	import { renderCosts } from './pages/costs.js';
 17	import { renderDatabases } from './pages/databases.js';
 18	import { renderDomains } from './pages/domains.js';
 19	import { renderEndpoints } from './pages/endpoints.js';
 20	import { renderFlags } from './pages/flags.js';
 21	import { renderHosts } from './pages/hosts.js';
 22	import { renderIncidents } from './pages/incidents.js';
 23	import { renderJobs } from './pages/jobs.js';
 24	import { renderMaintenance } from './pages/maintenance.js';
 25	import { renderOncall } from './pages/oncall.js';
 26	import { renderOverview } from './pages/overview.js';
 27	import { renderQueues } from './pages/queues.js';
 28	import { renderRegions } from './pages/regions.js';
 29	import { renderReports } from './pages/reports.js';
 30	import { renderRunbooks } from './pages/runbooks.js';
 31	import { renderSecrets } from './pages/secrets.js';
 32	import { renderServices } from './pages/services.js';
 33	import { renderSlos } from './pages/slos.js';
 34	import { renderStatus } from './pages/status.js';
 35	import { renderTeams } from './pages/teams.js';
 36	import { renderTokens } from './pages/tokens.js';
 37	import { renderVendors } from './pages/vendors.js';
 38	import { renderWebhooks } from './pages/webhooks.js';
 39	
 40	const PUBLIC_DIR = fileURLToPath(new URL('../public/', import.meta.url));
 41	const TYPES = { '.css': 'text/css', '.js': 'text/javascript', '.svg': 'image/svg+xml' };
 42	
 43	const ROUTES = {
 44	  '/': { title: 'Overview', snapshot: 'services', render: renderOverview },
 45	  '/services': { title: 'Services', snapshot: 'services', render: renderServices },
 46	  '/incidents': { title: 'Incidents', snapshot: 'incidents', render: renderIncidents },
 47	  '/oncall': { title: 'On-call', snapshot: 'oncall', render: renderOncall },
 48	  '/runbooks': { title: 'Runbooks', snapshot: 'runbooks', render: renderRunbooks },
 49	  '/alerts': { title: 'Alerts', snapshot: 'alerts', render: renderAlerts },
 50	  '/hosts': { title: 'Hosts', snapshot: 'hosts', render: renderHosts },
 51	  '/clusters': { title: 'Clusters', snapshot: 'clusters', render: renderClusters },
 52	  '/databases': { title: 'Databases', snapshot: 'databases', render: renderDatabases },
 53	  '/queues': { title: 'Queues', snapshot: 'queues', render: renderQueues },
 54	  '/jobs': { title: 'Jobs', snapshot: 'jobs', render: renderJobs },
 55	  '/certificates': { title: 'Certificates', snapshot: 'certificates', render: renderCertificates },
 56	  '/domains': { title: 'Domains', snapshot: 'domains', render: renderDomains },
 57	  '/costs': { title: 'Costs', snapshot: 'costs', render: renderCosts },
 58	  '/capacity': { title: 'Capacity', snapshot: 'capacity', render: renderCapacity },
 59	  '/slos': { title: 'SLOs', snapshot: 'slos', render: renderSlos },
 60	  '/maintenance': { title: 'Maintenance', snapshot: 'maintenance', render: renderMaintenance },
 61	  '/changes': { title: 'Changes', snapshot: 'changes', render: renderChanges },
 62	  '/flags': { title: 'Flags', snapshot: 'flags', render: renderFlags },
 63	  '/backups': { title: 'Backups', snapshot: 'backups', render: renderBackups },
 64	  '/tokens': { title: 'Tokens', snapshot: 'tokens', render: renderTokens },
 65	  '/teams': { title: 'Teams', snapshot: 'teams', render: renderTeams },
 66	  '/audit': { title: 'Audit log', snapshot: 'audit', render: renderAudit },
 67	  '/endpoints': { title: 'Endpoints', snapshot: 'endpoints', render: renderEndpoints },
 68	  '/regions': { title: 'Regions', snapshot: 'regions', render: renderRegions },
 69	  '/vendors': { title: 'Vendors', snapshot: 'vendors', render: renderVendors },
 70	  '/status': { title: 'Status', snapshot: 'status', render: renderStatus },
 71	  '/reports': { title: 'Reports', snapshot: 'reports', render: renderReports },
 72	  '/secrets': { title: 'Secrets', snapshot: 'secrets', render: renderSecrets },
 73	  '/webhooks': { title: 'Webhooks', snapshot: 'webhooks', render: renderWebhooks },
 74	};
 75	
 76	// Resolves one request to a response. Kept apart from the http server so
 77	// tests can call it directly.
 78	export async function handle(url, { dataDir } = {}) {
 79	  const { pathname, searchParams } = new URL(url, 'http://harbor.local');
 80	  if (pathname.startsWith('/public/')) return serveStatic(pathname.slice('/public/'.length));
 81	  const route = ROUTES[pathname];
 82	  if (!route) return page(404, 'Not found', '<h1>Not found</h1>', pathname);
 83	  let snapshot;
 84	  try {
 85	    snapshot = await readSnapshot(route.snapshot, dataDir);
 86	  } catch {
 87	    // The pipeline rewrites snapshots in place, so a read can fail for a
 88	    // moment. Say so instead of crashing; the next refresh usually works.
 89	    const body = `<h1>${escapeHtml(route.title)}</h1>
 90	<p class="muted">Snapshot unavailable, try again in a minute.</p>`;
 91	    return page(503, route.title, body, pathname);
 92	  }
 93	  return page(200, route.title, route.render(snapshot, Object.fromEntries(searchParams)), pathname);
 94	}
 95	
 96	function page(status, title, body, active) {
 97	  return { status, type: 'text/html; charset=utf-8', body: layout({ title, active, body }) };
 98	}
 99	
100	async function serveStatic(name) {
101	  const type = TYPES[extname(name)];
102	  if (name.includes('..') || !type) return { status: 404, type: 'text/plain', body: 'Not found' };
103	  try {
104	    return { status: 200, type, body: await readFile(join(PUBLIC_DIR, name), 'utf8') };
105	  } catch {
106	    return { status: 404, type: 'text/plain', body: 'Not found' };
107	  }
108	}
109	
110	if (process.argv[1] === fileURLToPath(import.meta.url)) {
111	  const { port, dataDir } = loadConfig();
112	  createServer(async (req, res) => {
113	    const out = await handle(req.url, { dataDir });
114	    res.writeHead(out.status, { 'content-type': out.type });
115	    res.end(out.body);
116	  }).listen(port, () => console.log(`harbor on http://localhost:${port}`));
117	}
